  const rows = data ?? [];
  const points: TrendPoint[] = [];
  for (let i = rows.length - 1; i >= 0; i--) {
    const row = rows[i];
    const value = row?.value_numeric;
    if (value == null || !Number.isFinite(value)) continue;
    points.push({ ts: row.ts, label: formatTime(row.ts), value });
